import{_ as e,o as n,c as a,ag as t}from"./chunks/framework.DC2anBTf.js";const h=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/architecture.md","filePath":"en/guide/architecture.md","lastUpdated":1793538094000}'),i={name:"en/guide/architecture.md"};function p(l,s,o,r,c,u){return n(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><h2 id="directory-structure" tabindex="-1">Directory Structure <a class="header-anchor" href="#directory-structure" aria-label="Permalink to &quot;Directory Structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes one-dark-pro github-light vp-code" tabindex="0"><code><span class="line"><span>├── main.uts                  # The only assembly point: app.use(router) + initRequest() + setupPermission()</span></span>
<span class="line"><span>├── App.uvue                  # App lifecycle (e.g. Android back-button interception)</span></span>
<span class="line"><span>├── pages.json / manifest.json</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── api/                      # API layer: thin wrappers (request forwarding + path consolidation + DTO restoration), no business logic</span></span>
<span class="line"><span>│   ├── user.uts</span></span>
<span class="line"><span>│   └── types.uts             # Single source of truth for DTOs (LoginResult / UserInfo, single file doubles as the aggregate export)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── stores/                   # State layer: ux-pinia class-style stores, mount-free (module-level registry as global singleton)</span></span>
<span class="line"><span>│   ├── index.uts             # useXxxStore exports</span></span>
<span class="line"><span>│   ├── types.uts             # Domain type aggregate export (forwards store class types)</span></span>
<span class="line"><span>│   └── modules/</span></span>
<span class="line"><span>│       └── user.uts          # UserStore class: state(reactive) + login/getInfo/logout/resetToken</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── composables/              # Composables: functions with no aggregate export (import directly as needed), types go through the aggregate export</span></span>
<span class="line"><span>│   ├── useLoading.uts</span></span>
<span class="line"><span>│   └── types.uts             # LoadingState definition (domain types in a single file)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── components/               # easycom convention directory (components/&lt;Name&gt;/&lt;Name&gt;.uvue, usable without registration)</span></span>
<span class="line"><span>│   └── AppLogo/AppLogo.uvue</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── router/                   # Routing layer</span></span>
<span class="line"><span>│   ├── index.uts             # createRouter (routes generated by the vite plugin)</span></span>
<span class="line"><span>│   ├── permission.uts        # Global guard: whitelist + token check + getInfo + redirects</span></span>
<span class="line"><span>│   └── routes.gen.uts        # ⚠ Auto-generated by @meng-xi/unix-router/vite-plugin, do not edit</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── utils/                    # Utility layer</span></span>
<span class="line"><span>│   ├── request.uts           # mx-request wrapper: configureRequest + dual interceptors</span></span>
<span class="line"><span>│   └── auth.uts              # Token read/write: in-memory cache (sync reads) + ux-storage persistence (async writes)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── config/</span></span>
<span class="line"><span>│   └── index.uts             # Single source of global config (appName / baseURL / timeout)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── pages/                    # Pages (uni-app x convention, statically registered in pages.json)</span></span>
<span class="line"><span>│   ├── index/index.uvue</span></span>
<span class="line"><span>│   └── login/login.uvue</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── types/                    # Plugin-generated d.ts (defineUniPage / RouteNameMap), never hold business types here</span></span>
<span class="line"><span>├── .trae/                    # AI-assisted development system (rules / skills / documents / mcp.json)</span></span>
<span class="line"><span>├── docs/                     # This documentation site (VitePress)</span></span>
<span class="line"><span>├── static/  uni.scss</span></span>
<span class="line"><span>└── uni_modules/              # Plugin suite + m-ui-x component library (zero-registration easycom)</span></span></code></pre></div><h2 id="core-call-chain" tabindex="-1">Core Call Chain <a class="header-anchor" href="#core-call-chain" aria-label="Permalink to &quot;Core Call Chain&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes one-dark-pro github-light vp-code" tabindex="0"><code><span class="line"><span>Page (.uvue)</span></span>
<span class="line"><span>  → composables/useXxx (cross-cutting UI state)</span></span>
<span class="line"><span>  → stores/modules/* (business state and actions)</span></span>
<span class="line"><span>  → api/&lt;domain&gt; (DTO restoration)</span></span>
<span class="line"><span>  → utils/request (interceptors: token injection + unified error toast)</span></span>
<span class="line"><span>  → mx-request → uni.request</span></span></code></pre></div><p>Three hard rules apply throughout:</p><ul><li><strong>Pages never touch the network layer directly</strong> and never see raw JSON; stores never reference components;</li><li><strong>The api layer only does thin wrapping</strong>: request forwarding + path consolidation + DTO restoration; business logic is forbidden;</li><li><strong>One assembly point</strong>: global initialization happens only in <code>main.uts</code>; side effects at module top level are forbidden.</li></ul><h2 id="startup-assembly-main-uts-the-only-assembly-point" tabindex="-1">Startup Assembly (main.uts, the only assembly point) <a class="header-anchor" href="#startup-assembly-main-uts-the-only-assembly-point" aria-label="Permalink to &quot;Startup Assembly (main.uts, the only assembly point)&quot;">​</a></h2><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes one-dark-pro github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-dark:#E5C07B;--shiki-light:#24292E;">app</span><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">.</span><span style="--shiki-dark:#61AFEF;--shiki-light:#6F42C1;">use</span><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#E06C75;--shiki-light:#24292E;">router</span><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">)      </span><span style="--shiki-dark:#7F848E;--shiki-dark-font-style:italic;--shiki-light:#6A737D;--shiki-light-font-style:inherit;">// ux-router: provide + global mixin (onShow syncRoute)</span></span>
<span class="line"><span style="--shiki-dark:#61AFEF;--shiki-light:#6F42C1;">initRequest</span><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">()        </span><span style="--shiki-dark:#7F848E;--shiki-dark-font-style:italic;--shiki-light:#6A737D;--shiki-light-font-style:inherit;">// mx-request: default instance config + dual interceptors (idempotent)</span></span>
<span class="line"><span style="--shiki-dark:#61AFEF;--shiki-light:#6F42C1;">setupPermission</span><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">()    </span><span style="--shiki-dark:#7F848E;--shiki-dark-font-style:italic;--shiki-light:#6A737D;--shiki-light-font-style:inherit;">// registers beforeEach + cold-start guardRoute() re-run of the guard chain</span></span></code></pre></div><p>Three assembly paradigms coexist <strong>not out of inconsistency but because the platform demands it</strong>: ux-router implements the Vue install protocol (reliable on Kotlin); ux-pinia is mount-free (<code>app.use</code> on native is verified not to work, so the module-level registry acts as the global singleton); mx-request is a pure function library (explicit initialization avoids timing issues with module top-level side effects).</p><h2 id="auth-guard-router-permission-uts" tabindex="-1">Auth Guard (router/permission.uts) <a class="header-anchor" href="#auth-guard-router-permission-uts" aria-label="Permalink to &quot;Auth Guard (router/permission.uts)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes one-dark-pro github-light vp-code" tabindex="0"><code><span class="line"><span>await ensureAuthReady()           // async guard (the ux-router guard chain supports await Promise)</span></span>
<span class="line"><span>├─ Has token</span></span>
<span class="line"><span>│   ├─ Visiting login page → redirect home</span></span>
<span class="line"><span>│   ├─ User info present → allow</span></span>
<span class="line"><span>│   └─ No user info → await getInfoAction</span></span>
<span class="line"><span>│       ├─ Success → allow</span></span>
<span class="line"><span>│       └─ Failure → resetToken + redirect to login (with redirect)</span></span>
<span class="line"><span>└─ No token</span></span>
<span class="line"><span>    ├─ Whitelisted (login page) → allow</span></span>
<span class="line"><span>    └─ Otherwise → redirect to login (query carries redirect=path)</span></span></code></pre></div><p>Three layers of protection:</p><ol><li><strong>Whitelist + token check</strong>: conventional guard semantics;</li><li><strong>Cold-start re-run</strong>: with H5 deep links / direct entry, the page may have loaded without the guard running — at startup <code>router.isReady().then(() =&gt; router.guardRoute(null, null))</code> explicitly re-runs the chain;</li><li><strong>Navigation interception fallback</strong>: the runtime enables <code>InterceptorPlugin</code> (<code>interceptUniApi: true</code>) to intercept raw native navigation such as <code>uni.navigateTo</code> and hand it to the guard chain — but the convention still requires going through <code>useRouter()</code>, never relying on the fallback.</li></ol><p><code>backFallback</code> is configured to the home page: when the page stack is too shallow after deep links / refresh and back() would fail, it automatically relaunches home (through the full guard chain) instead of failing with CANCELLED.</p><h2 id="assembly-points-unique-global-side-effects-nowhere-else" tabindex="-1">Assembly Points (unique; global side effects nowhere else) <a class="header-anchor" href="#assembly-points-unique-global-side-effects-nowhere-else" aria-label="Permalink to &quot;Assembly Points (unique; global side effects nowhere else)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Only Location</th></tr></thead><tbody><tr><td>Network init / interceptors</td><td><code>utils/request.uts</code> → <code>initRequest()</code> (idempotent guard)</td></tr><tr><td>Route guards</td><td><code>router/permission.uts</code> → <code>setupPermission()</code></td></tr><tr><td>Global config</td><td><code>config/index.uts</code></td></tr><tr><td>App lifecycle</td><td><code>App.uvue</code> (lifecycle logic only)</td></tr></tbody></table><p>main.uts stays minimal: <code>app.use(router)</code> + <code>initRequest()</code> + <code>setupPermission()</code>, with no additional assembly calls.</p>`,18)])])}const g=e(i,[["render",p]]);export{h as __pageData,g as default};
